begin;
create or replace function public.swift_region_catalogue() returns jsonb language sql stable security definer set search_path='' as $$select jsonb_build_object('districts',(select jsonb_agg(jsonb_build_object('id',id,'name',name) order by name) from public.swift_districts),'zones',(select jsonb_agg(jsonb_build_object('id',id,'name',name,'district_id',district_id,'active',active) order by name) from public.swift_service_zones),'stores',coalesce((select jsonb_agg(jsonb_build_object('category',r.category,'name',r.name,'logo',r.logo,'business_type',r.business_type,'zone_id',r.zone_id,'district_id',z.district_id,'status',r.status,'legacy',r.legacy,'latitude',m.latitude,'longitude',m.longitude)) from public.swift_store_registry r join public.swift_service_zones z on z.id=r.zone_id left join public.merchant_storefronts m on m.category=r.category where r.status='live' and z.active),'[]'::jsonb))$$;
commit;
